INSERT INTO public.quiz_questions (group_id, language, category, question, options, correct_index, explanation, source, is_active, sort_order)
VALUES
('7cb4800c-fa80-56a0-a10a-f57d6aaaf23d'::uuid, 'az', 'pregnancy', 'Hamiləlikdə gündəlik dəmir əlavəsi adətən nə qədər tövsiyə olunur?', '["5 mq", "500 mq", "30-60 mq", "Dəmir lazım deyil"]'::jsonb, 2, 'Dozanı qan analizinə görə həkim dəqiqləşdirir. Dəmiri çay və südlə eyni vaxtda içməmək daha yaxşıdır.', 'ÜST', true, 101),
('1853a3cd-56ab-5c20-ae4c-2611d51d9190'::uuid, 'az', 'pregnancy', 'Normal çəkili qadın hamiləlik boyu təxminən neçə kiloqram almalıdır?', '["Heç almamalıdır", "25-30 kq", "3-5 kq", "11,5-16 kq"]'::jsonb, 3, 'Hamiləlikdən əvvəlki çəki az və ya çox idisə, tövsiyə olunan artım fərqli olur.', 'IOM', true, 102),
('a176fe52-194e-5ecd-b5b9-0a0b3ce3dbce'::uuid, 'az', 'pregnancy', 'Göyöskürəyə qarşı peyvənd hamiləliyin hansı həftələrində tövsiyə olunur?', '["27-36-cı həftələrdə", "4-8-ci həftələrdə", "Yalnız doğuşdan sonra", "Heç vaxt"]'::jsonb, 0, 'Ananın anticisimləri körpəyə keçir və onu peyvəndə qədərki ilk aylarda qoruyur.', 'CDC', true, 103),
('ba1fcdd7-3190-5825-8623-a7f7fad439b5'::uuid, 'az', 'pregnancy', 'Qızılca-məxmərək (MMR) peyvəndi hamiləlikdə vurulurmu?', '["Bəli, istənilən vaxt", "Xeyr, hamiləlikdən əvvəl vurulmalıdır", "Bəli, ilk trimestrdə", "Yalnız son ayda"]'::jsonb, 1, 'Canlı peyvənddir. Peyvənddən sonra ən azı bir ay hamiləlikdən qorunmaq tövsiyə olunur.', 'CDC', true, 104),
('6b5650fc-9540-523c-9b28-0d9ebee24314'::uuid, 'az', 'pregnancy', 'Hamiləlikdə saunada və ya çox isti vannada uzun qalmaq haqqında hansı fikir doğrudur?', '["Bədən hərarətinin yüksəlməsi riskli ola bilər", "Tamamilə təhlükəsizdir", "Körpənin inkişafını sürətləndirir", "Ödemi tamamilə keçirir"]'::jsonb, 0, 'Xüsusilə ilk trimestrdə bədən istiliyinin çox qalxmasından çəkinmək lazımdır.', 'ACOG', true, 105),
('0d0cf0bd-2c4b-56a1-9874-20e87201e1d5'::uuid, 'az', 'pregnancy', 'Hamiləlikdə az civəli balıqdan həftədə nə qədər yemək tövsiyə olunur?', '["Ayda bir dəfə", "2-3 porsiya", "Heç yeməmək", "Hər gün 1 kq"]'::jsonb, 1, 'Qızılbalıq, sardina, alabalıq kimi balıqlar körpənin beyin inkişafı üçün faydalıdır.', 'FDA', true, 106),
('919ef232-bd52-5dd7-beb4-200dda159f36'::uuid, 'az', 'pregnancy', 'Hamiləlikdə əti necə bişirmək lazımdır?', '["Tam bişənə qədər, ortası çəhrayı qalmasın", "Yalnız qovrularaq üzdən", "Yarıbişmiş", "Çiy, limonla"]'::jsonb, 0, 'Yarıbişmiş ətdə hamiləlik üçün təhlükəli parazit və bakteriyalar ola bilər.', 'NHS', true, 107),
('7f28a97d-8d76-53c1-92df-00961c22a838'::uuid, 'az', 'pregnancy', 'Hamiləlikdə siqaret çəkmək hansı riski artırır?', '["Aşağı çəkili və vaxtından əvvəl doğuş", "Heç bir risk", "Uzun hamiləlik", "Böyük körpə"]'::jsonb, 0, 'Passiv siqaret tüstüsü də zərərlidir. Tərk etmək üçün heç vaxt gec deyil.', 'CDC', true, 108),
('fea9994c-b814-5146-a8f7-485081d3d431'::uuid, 'az', 'pregnancy', 'Hamiləlikdə diş həkiminə getmək olarmı?', '["Yalnız doğuşdan sonra", "Yalnız ağrı olanda", "Xeyr, qadağandır", "Bəli, müayinə və müalicə təhlükəsizdir"]'::jsonb, 3, 'Hamiləlikdə diş əti iltihabı tez-tez olur. Həkimə hamilə olduğunu de.', 'ACOG', true, 109),
('a2907623-219b-51ad-a271-d824e31e8fed'::uuid, 'az', 'pregnancy', 'Üçüncü trimestrdə körpənin hərəkətləri azalarsa, nə etmək lazımdır?', '["Bir neçə gün izləmək", "Dərhal həkimə müraciət etmək", "Səhərə qədər gözləmək", "Bu normaldır, heç nə"]'::jsonb, 1, 'Hərəkətin azalması körpənin yardıma ehtiyacı olduğunu göstərə bilər. Gözləmə.', 'NHS', true, 110),
('8ebced60-be66-5eff-b21f-287a8c7ead16'::uuid, 'az', 'pregnancy', 'Əsl doğuş sancıları hansı xüsusiyyətə malikdir?', '["Yalnız gecələr olan", "İstirahətlə tamamilə keçən", "Bir dəfə olub keçən", "Müntəzəm, getdikcə sıxlaşan və güclənən"]'::jsonb, 3, 'Sancılar arasındakı vaxtı qeyd et. Həkim nə vaxt gəlməli olduğunu deyəcək.', 'ACOG', true, 111),
('53d008f8-18b8-5c16-a5f0-32d3657fb110'::uuid, 'az', 'pregnancy', 'Braxton-Hiks (məşq) sancıları necə olur?', '["Nizamsız, zəif və istirahətlə keçən", "Həmişə qanaxma ilə", "Hər 3 dəqiqədən bir, getdikcə güclü", "Yalnız doğuş günü"]'::jsonb, 0, 'Bu sancılar uşaqlığın doğuşa hazırlığıdır və çox vaxt ikinci trimestrdən hiss olunur.', 'NHS', true, 112),
('3a976646-59f3-50ff-aa94-d75d774e0161'::uuid, 'az', 'pregnancy', 'Hamiləlikdə qəbizlik zamanı ilk növbədə nə kömək edir?', '["Yalnız ağ çörək", "Güclü işlətmə dərmanı", "Lifli qida, bol su və hərəkət", "Yeməyi azaltmaq"]'::jsonb, 2, 'Dəmir əlavəsi qəbizliyi artıra bilər. Dərman lazım olsa, həkimlə danış.', 'NHS', true, 113),
('50dee6ad-3b1c-5601-8dfb-8dedd8bf0135'::uuid, 'az', 'pregnancy', 'Hamiləlikdə ürək yanmasını azaltmaq üçün nə etmək olar?', '["Bol qazlı içki", "Az-az, tez-tez yemək, yeməkdən sonra uzanmamaq", "Gecə gec yemək", "Yeməkdən dərhal sonra yatmaq"]'::jsonb, 1, 'Yatağın baş tərəfini bir az qaldırmaq da kömək edir.', 'NHS', true, 114),
('c416bbe3-d4c3-56a9-ade2-f3fa73b84211'::uuid, 'az', 'pregnancy', 'Ağırlaşmasız hamiləlikdə təyyarə ilə adətən neçənci həftəyə qədər uçmaq olar?', '["Heç uçmaq olmaz", "Təxminən 36-cı həftəyə qədər", "Doğuş gününə qədər məhdudiyyətsiz", "Yalnız 12-ci həftəyə qədər"]'::jsonb, 1, 'Aviaşirkətlərin qaydaları fərqlidir. Uzun uçuşda tez-tez ayağa qalx və su iç.', 'ACOG', true, 115),
('d31ef4f0-2cdc-53e8-81b8-2028afd260f1'::uuid, 'az', 'pregnancy', 'Hamiləlikdə avtomobil kəmərini necə bağlamaq lazımdır?', '["Yalnız çiyindən", "Qarının tam üstündən", "Aşağı hissəsi qarının altından, budların üstündən", "Ümumiyyətlə bağlamamaq"]'::jsonb, 2, 'Çiyin hissəsi döş qəfəsinin ortasından keçməlidir.', 'ACOG', true, 116),
('df894919-1492-5cb2-bc2c-32058ed38c62'::uuid, 'az', 'pregnancy', 'Rezus-mənfi hamilə qadına adətən nə tövsiyə olunur?', '["Qan köçürmə", "Antibiotik kursu", "Anti-D immunoqlobulin", "Heç nə"]'::jsonb, 2, 'Adətən 28-ci həftə ətrafında və lazım olsa doğuşdan sonra vurulur.', 'ACOG', true, 117),
('6c068a8d-bf7f-5e18-9df2-a17cadaa453b'::uuid, 'az', 'pregnancy', 'Hamiləlikdə ultrasəs müayinəsi haqqında hansı fikir doğrudur?', '["Tibbi göstərişlə edildikdə təhlükəsizdir", "Qadağandır", "Yalnız bir dəfə olar", "Körpəyə zərər verir"]'::jsonb, 0, 'Müayinələrin sayını və vaxtını həkim müəyyən edir.', 'ACOG', true, 118),
('e98ae276-00b9-552e-8d2a-2149689329a6'::uuid, 'az', 'baby_food', 'Yeni doğulmuş körpənin mədəsi ilk gün təxminən nə boydadır?', '["Alma boyda", "Qarpız boyda", "Albalı boyda", "Stəkan boyda"]'::jsonb, 2, 'Ona görə ilk günlər az miqdarda ağız südü (kolostrum) kifayət edir.', 'AAP', true, 119),
('eac2d29d-4582-513f-98b8-12251c62a469'::uuid, 'az', 'baby_food', 'Ağız südü (kolostrum) nədir?', '["Sağılıb atılmalı olan zərərli süd", "Yalnız 6 aydan sonra gələn süd", "Anticisimlərlə zəngin ilk süd", "Süd qarışığının növü"]'::jsonb, 2, 'Kolostrum körpənin ilk "peyvəndi" sayılır. Onu körpəyə vermək çox faydalıdır.', 'ÜST', true, 120),
('f0becde4-be92-558e-89da-f31863c7b590'::uuid, 'az', 'baby_food', 'Körpənin kifayət qədər süd aldığını nə göstərir?', '["Çox yatması", "Gündə 6 və daha çox yaş bez və çəki artımı", "Hər əmizdirmədə ağlaması", "Gündə bir yaş bez"]'::jsonb, 1, 'Bu, adətən 5-ci gündən sonra keçərlidir. Şübhə varsa, körpəni çəkdir.', 'AAP', true, 121),
('cc617bd9-b465-5572-8cc8-94594d582a5c'::uuid, 'az', 'baby_food', 'Yeni doğulmuş körpə gündə neçə dəfə əmizdirilir?', '["Yalnız gecə", "Gündə 1 dəfə", "8-12 dəfə, tələbə görə", "3 dəfə, saatla"]'::jsonb, 2, 'Aclıq əlamətlərinə bax: əllərini ağzına aparır, dodaqlarını şapıldadır.', 'AAP', true, 122),
('cc559c0b-f0e6-56af-a63b-164e7711e87f'::uuid, 'az', 'baby_food', 'Dişi çıxmamış körpə yumşaq parça qidaları yeyə bilərmi?', '["Xeyr, bütün dişlər çıxmalıdır", "Yalnız 3 yaşdan sonra", "Bəli, diş ətləri ilə əzə bilir", "Yalnız maye qida olar"]'::jsonb, 2, 'Yumşaq, barmaqla əzilən qidalar diş olmadan da yeyilə bilər.', 'NHS', true, 123),
('7eb66a33-4bb8-51b9-9282-ed9d6327584f'::uuid, 'az', 'baby_food', 'Körpəni süd şüşəsi ilə yatağa qoymaq niyə tövsiyə olunmur?', '["Heç bir problemi yoxdur", "Süd soyuyur", "Çox yaxşı yatır", "Diş çürüməsi və boğulma riski var"]'::jsonb, 3, 'Yatmazdan əvvəl qidalandır, sonra şüşəni götür.', 'AAP', true, 124),
('d98de740-d9ca-5666-8910-f6524959ce90'::uuid, 'az', 'baby_food', 'Uşağın yeməyinə əlavə şəkər neçə yaşa qədər tövsiyə olunmur?', '["Hər yaşda olar", "2 yaşa qədər", "3 aylığa qədər", "6 aylığa qədər"]'::jsonb, 1, 'Şirin dad vərdişi erkən formalaşır. Meyvənin öz şirinliyi kifayətdir.', 'AAP', true, 125),
('a1adc297-9c22-5769-bf10-b001a40411ad'::uuid, 'az', 'baby_food', 'Körpəyə qara çay vermək haqqında hansı fikir doğrudur?', '["Süd yerinə verilir", "Hər gün faydalıdır", "Tövsiyə olunmur, dəmirin sorulmasını azaldır", "Sancıya qarşı mütləq lazımdır"]'::jsonb, 2, 'Bitki çaylarını da həkimlə məsləhətləşmədən vermə.', 'ÜST', true, 126),
('a98b6e09-7f42-5f0d-9321-806c33bb31cc'::uuid, 'az', 'baby_food', 'Yeni qidaları körpəyə necə təqdim etmək tövsiyə olunur?', '["Yalnız gecə", "Hamısını eyni gündə", "Yalnız qarışıq şəkildə", "Bir-bir, arada bir neçə gün fasilə ilə"]'::jsonb, 3, 'Belə etsən, reaksiya olarsa hansı qidadan olduğunu biləcəksən.', 'AAP', true, 127),
('7dfdcae0-5b16-5065-b2ca-5c4494661a21'::uuid, 'az', 'baby_food', 'Kiçik uşaq üçün hansı qida boğulma riski yaradır?', '["Yaxşı bişmiş yumşaq tərəvəz", "Yumşaq banan püresi", "Bütöv sosis dilimləri və popkorn", "Qatıq"]'::jsonb, 2, 'Sosisi uzununa doğra, popkorn və sərt konfetləri 4 yaşa qədər vermə.', 'AAP', true, 128),
('4cc47d51-3ea5-5500-a3df-d482e6c935af'::uuid, 'az', 'baby_food', 'Yemək zamanı öyümə ilə boğulmanın fərqi nədir?', '["Öyümə səsli qorunma refleksidir, boğulma çox vaxt səssizdir", "Boğulma həmişə səslidir", "Öyümə həmişə təhlükəlidir", "Heç bir fərq yoxdur"]'::jsonb, 0, 'Öyüyəndə körpəyə mane olma. Səssiz qalarsa və nəfəs ala bilmirsə, ilk yardım lazımdır.', 'NHS', true, 129),
('3105d959-7489-583d-aa20-5d435261c90e'::uuid, 'az', 'baby_food', 'Bitki mənşəli dəmirin sorulmasını nə artırır?', '["C vitamini ilə zəngin qida", "Çay", "Qəhvə", "Süd ilə birlikdə yemək"]'::jsonb, 0, 'Məsələn, mərcimək yeməyinin yanında pomidor və ya bibər ver.', 'ÜST', true, 130),
('4d29ad79-5e4f-5676-89ae-0a125a4eff8e'::uuid, 'az', 'baby_food', 'Süd qarışığını hazırlamaq üçün su necə olmalıdır?', '["Qaynadılıb ən azı 70°C-ə qədər soyumuş", "Qaynar, yenicə qaynamış", "Mineral qazlı su", "Soyuq kran suyu"]'::jsonb, 0, 'Bu temperatur tozda ola biləcək bakteriyaları öldürür. Sonra qarışığı içilə biləcək istiliyə qədər soyut.', 'ÜST', true, 131),
('e0bc07ca-6618-54d3-8a2e-d15f8ad1a912'::uuid, 'az', 'baby_food', 'Hazırlanmış süd qarışığı otaq temperaturunda nə qədər qala bilər?', '["24 saat", "Məhdudiyyət yoxdur", "Təxminən 2 saat", "2 gün"]'::jsonb, 2, 'Körpə içməyə başlayıbsa, qalanını bir saat ərzində istifadə et və ya at.', 'CDC', true, 132),
('41a4512f-68d7-5b69-b639-c20a16dd43cc'::uuid, 'az', 'baby_food', 'Körpənin toxluq əlaməti hansıdır?', '["Başını çevirir, ağzını yumur", "Əllərini ağzına aparır", "Dodaqlarını şapıldadır", "Ağlayır və axtarır"]'::jsonb, 0, 'Toxluq əlamətlərinə hörmət etmək sağlam yemək vərdişi formalaşdırır.', 'AAP', true, 133),
('915a65fd-bcdd-5d69-a18c-a9382cb0b33e'::uuid, 'az', 'baby_food', 'Vegetarian ailədə körpənin qidalanmasında nəyə xüsusi diqqət etmək lazımdır?', '["B12, dəmir və proteinə", "Duzun artırılmasına", "Yalnız şəkərə", "Heç nəyə"]'::jsonb, 0, 'Həkim və ya dietoloqla plan qurmaq ən yaxşısıdır.', 'AAP', true, 134),
('510d52fa-a950-5617-b18a-dd47276ad32f'::uuid, 'az', 'sleep', 'Yeni doğulmuşun gecə tez-tez oyanması haqqında hansı fikir doğrudur?', '["Qidalanmaq üçün oyanması normaldır", "Mütləq xəstəlik əlamətidir", "Yalnız pis vərdişdir", "Onu oyanmamağa öyrətmək lazımdır"]'::jsonb, 0, 'İlk aylarda kiçik mədə gecə də qidalanma tələb edir.', 'AAP', true, 135),
('4666f993-d6b1-57e3-9d59-c6ab9d7daf2f'::uuid, 'az', 'sleep', 'Yatmazdan əvvəl hər gün eyni rejim (ritual) nə üçün faydalıdır?', '["Yalnız böyüklər üçündür", "Yuxunu qısaldır", "Heç bir təsiri yoxdur", "Yuxuya getməyi asanlaşdırır"]'::jsonb, 3, 'Məsələn: çimmək, pijama, kitab, layla. Hər axşam eyni sıra ilə.', 'AAP', true, 136),
('70171097-b110-54df-9de3-550722aab9a7'::uuid, 'az', 'sleep', 'Ağ səs cihazından necə istifadə etmək lazımdır?', '["Maksimum səslə, qulağının yanında", "Aşağı səslə və beşikdən uzaqda", "Bütün gecə ən yüksək səslə", "Yastığın altında"]'::jsonb, 1, 'Çox yüksək və yaxın səs körpənin eşitməsinə zərər verə bilər.', 'AAP', true, 137),
('63f7b4e3-858e-56ca-96a1-2851a7d244b7'::uuid, 'az', 'sleep', 'Körpəni yuxulu, amma oyaq ikən beşiyə qoymaq nə üçün faydalıdır?', '["Gecə daha çox oyanır", "Daha çox ağlayır", "Özü yuxuya getməyi öyrənir", "Heç bir faydası yoxdur"]'::jsonb, 2, 'Bu bacarıq bir anda yox, həftələr ərzində formalaşır.', 'AAP', true, 138),
('5ad96e23-977f-52bf-a935-c9b2afb30347'::uuid, 'az', 'sleep', 'Körpəni evdə yatırarkən papaq geyindirmək lazımdırmı?', '["Bəli, qalın papaq", "Yalnız yayda", "Xeyr, qızma riski var", "Bəli, həmişə"]'::jsonb, 2, 'Körpə başı ilə istilik verir. Evdə yuxuda baş açıq olmalıdır.', 'NHS', true, 139),
('a61dc901-9bad-58cd-a076-be6b9cd7047a'::uuid, 'az', 'sleep', 'Gecə qidalandırarkən nə etmək körpəyə gecə ilə gündüzü ayırmağa kömək edir?', '["Parlaq işığı yandırmaq", "Televizoru açmaq", "Zəif işıq və sakit səs, oyun oynamamaq", "Körpə ilə aktiv oynamaq"]'::jsonb, 2, 'Gündüz isə işıq, səs və oyun olsun. Bu fərq bioloji saatı qurur.', 'NHS', true, 140),
('d0622ec8-9de4-5a66-9fae-321112743dc5'::uuid, 'az', 'sleep', 'Uşaq hər gecə bərkdən xoruldayır və nəfəsi arabir dayanırsa, nə etmək lazımdır?', '["Həkimə müraciət etmək", "Yastığı çoxaltmaq", "Gec yatırtmaq", "Normaldır, heç nə"]'::jsonb, 0, 'Bu, yuxu apnoesinin əlaməti ola bilər. Çox vaxt böyümüş badamcıqlarla bağlıdır və müalicə olunur.', 'AAP', true, 141),
('50f3e947-e56e-52bd-88ec-fa61b661e508'::uuid, 'az', 'sleep', 'Uşaqlar gündüz yuxusundan adətən nə vaxt imtina edir?', '["10 yaşda", "1 yaşda", "6 aylıqda", "3-5 yaş arasında"]'::jsonb, 3, 'Gündüz yatmayan uşağa sakit istirahət vaxtı yenə faydalıdır.', 'AAP', true, 142),
('28b45c82-277f-5327-ac02-bfd75ab0c5b2'::uuid, 'az', 'sleep', 'Gecə qorxusu (uşaq yuxuda qışqırır, amma oyanmır) zamanı nə etmək lazımdır?', '["Cəzalandırmaq", "Güclə oyatmaq", "Soyuq su səpmək", "Oyatmağa çalışmamaq, təhlükəsizliyini qorumaq"]'::jsonb, 3, 'Uşaq səhər adətən heç nə xatırlamır. Tez-tez olarsa, həkimə de.', 'AAP', true, 143),
('cc1aa508-8022-5273-819f-17874f973d50'::uuid, 'az', 'sleep', 'Körpənin olduğu otaqda siqaret çəkmək nəyi artırır?', '["İştahanı", "Ani körpə ölümü riskini", "Heç nəyi", "Yuxunun keyfiyyətini"]'::jsonb, 1, 'Evdə və maşında tamamilə siqaretsiz mühit ən yaxşısıdır.', 'AAP', true, 144),
